static int install(void*c,uint64_t epoch,int alg,const uint8_t*peer,int index,int tx,const uint8_t*seq,size_t seq_bytes,const uint8_t*key,size_t key_bytes,unsigned flags){(void)c;child.borrowed++;int r=child.providers.install_confirmed(child.providers.context,epoch,alg,peer,index,tx,seq,seq_bytes,key,key_bytes,flags);child.borrowed--;return r;}
