static void close_io(void*c,uint64_t epoch,unsigned why){revoked(c,epoch,why);}
static unsigned allocations(void){unsigned n=0;for(unsigned j=0;j<128;j++)n+=runtime.allocation[j].used!=0;return n;}
static unsigned timers(void){unsigned n=0;for(unsigned j=0;j<64;j++)n+=runtime.timers[j].used!=0;return n;}
static Status close_context(void){if(child.borrowed||runtime.dispatching)return EFI_ERROR(3);if(!child.opened)return child.quarantined?EFI_ERROR(3):0;io.closed=1;rsn_runtime_revoke(&runtime,1);if(child.sm_context&&child.sm_context->cancel_auth_timeout)child.sm_context->cancel_auth_timeout(child.sm_context->ctx);if(io.sm){wpa_sm_deinit(io.sm);io.sm=0;child.sm_context=0;}if(allocations()||timers()||!rsn_runtime_unbind(&runtime)){child.quarantined=1;return EFI_ERROR(3);}wipe(&io,sizeof io);child.opened=0;wipe(&child.providers,sizeof child.providers);return 0;}
